<?php
declare(strict_types=1);
require __DIR__.'/../app/analytics/PublicDashboardService.php';
function dashCheck(bool $v,string $msg):void{if(!$v)throw new RuntimeException($msg);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$db->exec("CREATE TABLE destinations(id INTEGER PRIMARY KEY,slug TEXT,department TEXT,country_code TEXT,publication_status TEXT);INSERT INTO destinations VALUES(1,'jerico','Antioquia','CO','published'),(2,'cauca-viejo','Antioquia','CO','published'),(3,'jardin','Antioquia','CO','draft'),(4,'bogota','Bogotá D.C.','CO','published');CREATE TABLE accounts(id INTEGER,account_type TEXT,status TEXT,email_verified_at TEXT,email TEXT);INSERT INTO accounts VALUES(1,'traveler','active','2026-01-01','real@example.org'),(2,'traveler','active','2026-01-01','admin@example.org'),(3,'traveler','active',NULL,'pending@example.org'),(4,'traveler','active','2026-01-01','test@pruebas.invalid');CREATE TABLE account_roles(account_id INTEGER,role TEXT);INSERT INTO account_roles VALUES(2,'administrator');CREATE TABLE businesses(id INTEGER PRIMARY KEY,destination_id INTEGER,public_id TEXT,publication_status TEXT,information_status TEXT,operation_status TEXT);CREATE TABLE business_subscriptions(id INTEGER PRIMARY KEY,business_id INTEGER,plan_code TEXT,status TEXT,starts_at TEXT,ends_at TEXT);CREATE TABLE business_account_memberships(business_id INTEGER,status TEXT);");
for($i=1;$i<=7;$i++)$db->exec("INSERT INTO businesses VALUES($i,".($i===4?2:($i===5?3:1)).",'business-$i','".($i===6?'draft':'published')."','PUBLICO','ABIERTO')");
$db->exec("UPDATE businesses SET public_id='f00d0000-fixture' WHERE id=7;INSERT INTO business_subscriptions VALUES(1,1,'featured','active','2020-01-01',NULL),(2,1,'page_premium','pending_payment',NULL,NULL),(3,2,'page_premium','active','2020-01-01','2021-01-01'),(4,3,'page','active','2099-01-01',NULL),(5,4,'page','active','2020-01-01',NULL);INSERT INTO business_account_memberships VALUES(1,'active'),(1,'active');CREATE TABLE el_basic_settings(setting_key TEXT,setting_value TEXT);INSERT INTO el_basic_settings VALUES('enabled','1');CREATE TABLE el_basic_entity_daily(page_day TEXT,entity_type TEXT,entity_key TEXT,metric TEXT,metric_count INTEGER);");
$today=(new DateTimeImmutable('now',new DateTimeZone('America/Bogota')))->format('Y-m-d');$q=$db->prepare("INSERT INTO el_basic_entity_daily VALUES(?,'destination',?,'page_view',?)");foreach(['jerico'=>7,'cauca-viejo'=>3,'jardin'=>99] as $key=>$n)$q->execute([$today,$key,$n]);
$svc=new PublicDashboardService($db);$deps=[['code'=>'05','name'=>'Antioquia'],['code'=>'11','name'=>'Bogotá D. C.']];$r=$svc->report($deps);
dashCheck($r['registered_travelers']===1,'Only confirmed non-admin, non-test traveler accounts');dashCheck($r['businesses']['total']===4,'Only published non-test businesses of published places');dashCheck($r['businesses']['by_subscription']['featured']===1&&$r['businesses']['by_subscription']['free']===2&&$r['businesses']['by_subscription']['page']===1,'Current active subscription only; expired/future/pending must not inflate paid counts');dashCheck($r['businesses']['with_registered_responsible']===1,'Memberships do not duplicate businesses');dashCheck(!str_contains(json_encode($r),'jardin'),'Drafts never appear in dashboard');
$capital=$svc->report([...$deps,['code'=>'25','name'=>'Cundinamarca']],'25',null,7);dashCheck(count($capital['places'])===1&&$capital['places'][0]['slug']==='bogota','Cundinamarca navigation includes the capital without changing source geography');
$r=$svc->report($deps,'05','cauca-viejo');dashCheck($r['businesses']['total']===1&&$r['place_interest']['rows'][0]['views']===3,'Independent place filtering');dashCheck($r['registered_travelers']===1,'Traveler community stays portal-wide');
$db->exec('DROP TABLE el_basic_settings');$r=$svc->report($deps);dashCheck($r['place_interest']['status']==='not_configured'&&$r['businesses']['total']===4,'Unavailable measurement is not zero and does not hide catalogue data');
echo "OK: aggregate public dashboard, current plans, protected drafts, independent places and no admin/test accounts.\n";
